-- CDMNP-1573 - Opening support tickets
/*
-- Issue Description: 
    Move Approved CW & PROV Tickets to unapproved status for the ones which not created JIRA ID
	
-- Category/ Module: Contact Support Ticket
-- Root cause: Issue on ESMS 
-- Fix Provided: Datafix was promoted to update the Contact Support Ticket as Pending.  
-- Pull request# N/A
-- Reason why no related code fix: N/A
-- Status of the code fix if already submitted and expected prod fix date: N/A
*/

-- Delete Duplicate supportno record - S20200238014594

select supportlogid, jirarequestsent, updatedby, updatedon, jirarequestno, supportno 	
	from defecttracking.supportlog
where activeflag = 1
	and jiraenv = 'Production'
	and coalesce(jirarequestsent, 'Pending') not in ( 'Approve', 'Approved')
	and jirarequestno is null
	and supportno = 'S20200238014594'
	and supportlogid in ( 'eb5e496d-237c-4fc0-802e-579fff67421b', 
						  '12a8770d-4d14-46d3-90dd-729e659bfdec'
						 ) ;
	
update defecttracking.supportlog
set activeflag = 0,
	updatedby  = 'CDMNP-1573-R3',
	updatedon  = now()
where activeflag = 1
	and jiraenv = 'Production'
	and coalesce(jirarequestsent, 'Pending') not in ( 'Approve', 'Approved')
	and jirarequestno is null
	and supportno = 'S20200238014594'
	and supportlogid in ( 'eb5e496d-237c-4fc0-802e-579fff67421b', 
						  '12a8770d-4d14-46d3-90dd-729e659bfdec'
						 ) ;

update defecttracking.supportlog
set program = (case when (program is null or btrim(program) = '') then
					'In-Home'
			   else
					program
			   end),
	updatedby  = 'CDMNP-1573-R3',
	updatedon  = now()
where activeflag = 1
	and jiraenv = 'Production'
	and coalesce(jirarequestsent, 'Pending') not in ( 'Approve', 'Approved')
	and jirarequestno is null
	and supportno = 'S20200238014594'
	and supportlogid = '2a6b5d7a-0d70-4010-8881-b7da234bcb46';

